"""Author-maintained recipe drafts. No scraped recipe text or third-party recipe images."""
import json
from pathlib import Path
rows=[]
def add(id,name,cuisine,role,time,items,steps,optional=''):
    def parse(s):
        return [dict(zip(['id','quantity','unit'],[a,float(b),c])) for a,b,c in (v.split(':') for v in s.split('|') if v)]
    rows.append(dict(id=id,name=name,cuisine=cuisine,role=role,time=time,servings=2,items=parse(items),optional=parse(optional),steps=steps.split('~'),provenance={'author':'Fridge & Fork / AI-assisted draft','created':'2026-10-12','origin':'Independently composed for this app from general cooking methods; not copied from a recipe publication.','rights':'No third-party recipe text or photos incorporated in this record. No guarantee of exclusive copyright.','testingStatus':'not-kitchen-tested','testDate':None,'reviewer':None}))
add('fried-rice','Simple egg fried rice','International','starch',15,'cooked rice:300:g|eggs:2:piece|oil:15:ml|salt:1:g','Break apart the chilled cooked rice and beat the eggs in a bowl.~Heat half the oil in a wide pan over medium heat. Scramble the eggs until set, then lift them onto a clean plate.~Add the remaining oil and rice. Stir and turn for 4–6 minutes, breaking up clumps, until hot throughout.~Return the eggs, add the salt and stir together for one minute. Use the reheating guidance below before serving.','garlic:2:clove|spring onion:1:piece')
add('tomato-pasta','Easy tomato & garlic pasta','International','main',25,'dry pasta:180:g|tomatoes:350:g|garlic:3:clove|oil:20:ml|salt:1:g','Cook the dry pasta in boiling water according to its packet. Keep a cup of cooking water before draining.~Chop the tomatoes and mince the garlic. Warm the oil in a pan, then stir the garlic for 30 seconds without browning it.~Add tomatoes and salt. Simmer for 12–15 minutes, crushing the pieces as they soften.~Toss in the pasta. Add a little reserved water until the sauce coats it. Serve hot.','pepper:0.5:g')
add('omelette','Spinach & cheese omelette','International','main',15,'eggs:4:piece|spinach:80:g|cheese:50:g|oil:10:ml|salt:1:g','Wash and chop the spinach. Beat the eggs with salt and grate the cheese.~Heat half the oil in a nonstick pan. Cook spinach until wilted, then transfer to a bowl.~Add the rest of the oil and pour in the eggs. Cook gently, lifting the edges so uncooked egg can flow underneath.~Spread spinach and cheese over half. Fold and continue cooking gently until the center is set; follow the egg-dish temperature note below.')
add('potato-hash','Golden potato & egg hash','International','main',30,'potatoes:350:g|onion:1:piece|eggs:2:piece|oil:20:ml|salt:1:g','Cut potatoes into 1 cm cubes and chop the onion. Boil potatoes for 6–8 minutes until nearly tender; drain well.~Heat oil in a wide pan. Add potatoes and onion, then cook for 10–12 minutes, turning until browned and tender.~Season with salt and make two spaces for the eggs. Crack an egg into each.~Cover and cook gently until the whites and yolks are firm. Divide between plates.')
add('cucumber-salad','Tomato cucumber salad','International','side',10,'cucumber:250:g|tomatoes:250:g|onion:0.5:piece|lemon juice:15:ml|oil:10:ml|salt:1:g','Wash the cucumber and tomatoes and cut into bite-size pieces. Slice the onion thinly.~Mix lemon juice, oil and salt in a bowl.~Toss the vegetables in the dressing immediately before serving.')
add('chickpea-skillet','Tomato chickpea skillet','International','main',25,'cooked chickpeas:300:g|tomatoes:300:g|spinach:80:g|garlic:2:clove|oil:15:ml|salt:1:g','Drain the cooked chickpeas. Chop the tomatoes and garlic; wash spinach.~Heat oil in a pan. Stir garlic for 30 seconds, then add tomatoes and salt.~Simmer for 10–12 minutes until saucy, adding a splash of water if it sticks.~Add chickpeas and simmer five minutes. Fold in spinach and cook until wilted and hot.')
add('toast','Cheesy tomato toast','International','starch',10,'bread:4:slice|tomatoes:200:g|cheese:60:g','Slice the washed tomatoes and grate the cheese.~Lightly toast the bread. Cover it with tomatoes and cheese.~Place under a hot grill or broiler, watching continuously, until the cheese is melted. Serve immediately.','pepper:0.5:g')
add('mushrooms','Garlic mushroom rice bowl','International','main',15,'mushrooms:200:g|cooked rice:300:g|garlic:2:clove|soy sauce:15:ml|oil:15:ml','Slice the mushrooms and mince the garlic. Break apart the chilled rice.~Heat oil in a wide pan and cook mushrooms for 6–8 minutes until browned.~Stir in garlic for 30 seconds, then add soy sauce and the rice.~Toss until the rice is steaming hot throughout, following the reheating note below.')
add('sinangag','Sinangag-style garlic rice','Filipino','starch',15,'cooked rice:300:g|garlic:5:clove|oil:20:ml|salt:1:g','Break the chilled rice into loose grains and finely chop the garlic.~Warm oil over medium-low heat. Stir the garlic until pale gold, then scoop half out to prevent burning.~Add rice and salt to the pan. Toss and turn until fully reheated.~Scatter the reserved garlic over the rice and serve. See the rice storage note below.')
add('chicken-adobo','Simple chicken adobo','Filipino','main',45,'chicken thigh:400:g|soy sauce:30:ml|vinegar:30:ml|garlic:4:clove|oil:10:ml|pepper:1:g','Cut boneless chicken thigh into large pieces on a separate board. Crush the garlic.~Heat oil in a saucepan and brown the chicken lightly on both sides.~Add garlic, soy sauce, vinegar, pepper and 150 ml water. Bring to a boil, then cover and simmer for 20–25 minutes.~Uncover and reduce the sauce for 5–10 minutes, turning the chicken. Check its internal temperature before serving.','bay leaf:1:piece')
add('pork-adobo','Simple pork adobo','Filipino','main',60,'pork shoulder:400:g|soy sauce:30:ml|vinegar:30:ml|garlic:4:clove|oil:10:ml|pepper:1:g','Cut pork shoulder into 2 cm cubes and crush the garlic.~Heat oil in a heavy saucepan and brown pork in a single layer, working in batches if needed.~Add garlic, soy sauce, vinegar, pepper and 250 ml water. Bring to a boil and cover.~Simmer 40–45 minutes or until tender, adding water if needed. Uncover to thicken the sauce and check the pork temperature.','bay leaf:1:piece')
add('giniling','Tomato pork giniling','Filipino','main',35,'ground pork:250:g|potatoes:200:g|carrots:100:g|tomatoes:250:g|onion:1:piece|garlic:2:clove|oil:15:ml|salt:2:g','Finely chop onion and garlic. Cut potatoes and carrots into small even cubes; chop tomatoes.~Heat oil in a pan. Soften onion for three minutes, then add garlic and ground pork. Break the meat into small pieces.~Add tomatoes, potatoes, carrots, salt and 150 ml water. Cover and simmer 15–20 minutes until vegetables are tender.~Uncover to reduce excess liquid. Stir thoroughly and verify the ground pork temperature before serving.')
add('tortang-talong','Tortang talong-style eggplant omelette','Filipino','main',35,'eggplant:300:g|eggs:3:piece|oil:20:ml|salt:1:g','Prick the eggplant and grill or broil, turning carefully, until its flesh is completely soft, about 15–20 minutes.~Cool enough to handle, peel off the skin and flatten the flesh with a fork.~Beat eggs with salt and coat the flattened eggplant in the mixture.~Heat oil in a nonstick pan. Cook the eggplant with the remaining egg mixture on both sides until set throughout. Check the egg-dish temperature.')
add('sayote','Ginisang sayote','Filipino','side',20,'chayote:350:g|onion:0.5:piece|garlic:2:clove|oil:15:ml|salt:1:g','Peel the chayote, remove the seed and slice the flesh thinly. Chop onion and garlic.~Heat oil in a pan and soften onion for three minutes. Add garlic for 30 seconds.~Add chayote, salt and 60 ml water. Cover and cook for 8–10 minutes until just tender.~Remove the lid and let excess water evaporate. Serve as a vegetable side.')
add('cabbage-eggs','Ginisang repolyo with eggs','Filipino','side',20,'cabbage:300:g|eggs:2:piece|onion:0.5:piece|garlic:2:clove|oil:15:ml|salt:1:g','Shred washed cabbage, chop onion and garlic, and beat the eggs.~Heat oil in a wide pan. Soften onion, then briefly stir in garlic.~Add cabbage, salt and 30 ml water. Stir-fry until tender but not mushy.~Push cabbage aside, add eggs and scramble until set. Mix together and cook until the egg dish reaches the temperature below.')
add('tofu-adobo','Tofu adobo-style skillet','Filipino','main',25,'firm tofu:300:g|soy sauce:25:ml|vinegar:20:ml|garlic:3:clove|oil:20:ml|pepper:0.5:g','Drain and pat the tofu dry. Cut into cubes and mince the garlic.~Heat oil in a nonstick pan and brown tofu on several sides.~Add garlic, soy sauce, vinegar, pepper and 60 ml water. Bring to a simmer.~Cook gently for 5–8 minutes, turning the tofu until coated with the reduced sauce.')
add('tinola','Simple chicken tinola','Filipino','main',40,'chicken thigh:400:g|chayote:250:g|spinach:80:g|ginger:20:g|onion:1:piece|garlic:2:clove|oil:15:ml|salt:2:g','Cut boneless chicken into large pieces. Peel and slice chayote and ginger; chop onion and garlic.~Heat oil in a saucepan. Soften onion and ginger for three minutes, then add garlic and chicken.~Pour in 700 ml water and add salt. Bring to a boil, then simmer for 20 minutes.~Add chayote and simmer until tender, around 8–10 minutes. Verify chicken temperature, then stir in spinach until wilted.')
add('arroz-caldo','Simple chicken arroz caldo','Filipino','main',45,'uncooked rice:100:g|chicken thigh:250:g|ginger:20:g|onion:1:piece|garlic:3:clove|oil:15:ml|salt:2:g','Rinse the uncooked rice. Chop the onion, garlic and ginger; cut boneless chicken into small pieces.~Heat oil in a pot. Soften onion and ginger, then add garlic and chicken.~Add rice, salt and 900 ml water. Bring to a boil and simmer gently, stirring often, for 30–35 minutes.~Add more water if needed for a spoonable porridge. Check chicken temperature and rice tenderness before serving.','spring onion:1:piece')
add('sardine-tomato','Sardines with fresh tomatoes','Filipino','main',15,'canned sardines:200:g|tomatoes:250:g|onion:1:piece|garlic:2:clove|oil:10:ml','Drain plain canned sardines. Chop tomatoes, onion and garlic.~Warm oil in a pan. Soften onion for four minutes, then stir in garlic.~Add tomatoes and cook for 5–7 minutes until broken down, adding a splash of water if dry.~Lay the sardines in the sauce and warm gently without breaking them up too much.')
add('munggo','Quick ginisang munggo','Filipino','main',25,'cooked mung beans:350:g|tomatoes:200:g|spinach:80:g|onion:1:piece|garlic:2:clove|oil:15:ml|salt:2:g','Use already cooked, soft mung beans. Chop tomatoes, onion and garlic, and wash spinach.~Heat oil in a saucepan. Soften onion, then add garlic and tomatoes.~Cook until tomatoes soften. Add mung beans, salt and 300 ml water. Simmer for 10 minutes, crushing a few beans to thicken.~Stir in spinach and cook until wilted. Adjust thickness with water.')
